def decide(self, reports: list[AgentReport]) -> ConsensusDecision:
    settings = get_settings()
    if not reports:
        return ConsensusDecision("review", 0.5, 0.0, ["no signals available"])

    weighted_sum = sum(r.score * r.weight for r in reports)
    weight_total = sum(r.weight for r in reports)
    base_score = weighted_sum / max(weight_total, 1e-6)

    # Override: a confident, well-weighted extreme signal wins.
    overrides = [r for r in reports if r.score >= 0.95 and r.weight >= 1.0]
    if overrides:
        base_score = max(base_score, max(r.score for r in overrides))

    # Confidence = 1 − mean(distance from consensus), clipped.
    spread = sum(abs(r.score - base_score) for r in reports) / len(reports)
    confidence = float(max(0.0, min(1.0, 1.0 - spread)))

    # Verdict via configured thresholds.
    if base_score >= settings.block_threshold:
        verdict = "block"
    elif base_score >= settings.review_threshold:
        verdict = "review"
    else:
        verdict = "approve"

    # Top reasons — order agents by risk contribution (score * weight).
    ranked = sorted(reports, key=lambda r: r.score * r.weight, reverse=True)
    reasons: list[str] = []
    for r in ranked:
        if r.score < 0.1:
            continue
        reasons.append(f"[{r.agent}] {r.rationale}")
        if len(reasons) >= 3:
            break
    if not reasons:
        reasons = ["All signals nominal."]

    return ConsensusDecision(
        verdict=verdict,
        risk_score=float(round(base_score, 4)),
        confidence=float(round(confidence, 4)),
        top_reasons=reasons,
    )

def main():
    src, out = sys.argv[1], sys.argv[2]
    runs = {}
    for f in glob.glob(os.path.join(src, "*.json")):
        d = json.load(open(f))
        if "bug" in d:
            runs[d["bug"]] = d["suites"]
    baseline = runs.get("NONE", {})
    bugs = sorted(b for b in runs if b != "NONE")
    suites = [s for s in ORDER if any(s in runs[b] for b in runs)]
    matrix = {}
    for b in bugs:
        matrix[b] = {}
        for s in suites:
            r = runs[b].get(s)
            base = baseline.get(s)
            if r is None:
                cell = {"status": "not-run"}
            elif base is None:
                cell = {"status": "no-baseline", "failed": r["failed"], "tests": r["tests"]}
            elif base["detected"]:
                cell = {"status": "baseline-red", "failed": r["failed"], "tests": r["tests"]}
            else:
                cell = {"status": "caught" if r["detected"] else "escaped", "failed": r["failed"],
                        "tests": r["tests"], "exit_code": r["exit_code"], "seconds": r["seconds"],
                        "failures": r["failures"][:12]}
            matrix[b][s] = cell
    caught_by = {b: [s for s in suites if matrix[b][s]["status"] == "caught"] for b in bugs}
    rate = {s: (sum(1 for b in bugs if matrix[b][s]["status"] == "caught") / len(bugs)) if bugs else 0
            for s in suites}
    result = {"baseline": baseline, "bugs": bugs, "suites": suites, "matrix": matrix,
              "detection_rate_per_suite": rate, "caught_by": caught_by,
              "escaped_all": [b for b in bugs if not caught_by[b]]}

// ── 4 + 5. VERIFY → DEBUG loop (operates on the agent-authored files) ─────
let iteration = 0;
while (iteration < maxIterations) {
  emit({ type: "phase", agent: "verifier", status: "start" });
  const verOut = await runAgent(
    VERIFIER_SYSTEM,
    `Audit these files.\n\n${filesToContext(appFiles)}`,
    (d) => emit({ type: "token", agent: "verifier", text: d }),
    3000
  );
  account(verOut);
  const issues = extractJson<Issue[]>(verOut.text) ?? [];
  issuesFound += issues.length;
  emit({ type: "issues", issues, iteration });
  emit({ type: "phase", agent: "verifier", status: "done" });

  const blocking = issues.filter(
    (i) => i.severity === "critical" || i.severity === "warning"
  );
  if (blocking.length === 0) break;

  debugIterations++;
  emit({ type: "phase", agent: "debugger", status: "start" });
  const dbgOut = await runAgent(
    DEBUGGER_SYSTEM,
    `Current files:\n\n${filesToContext(appFiles)}\n\nIssues to fix:\n${JSON.stringify(blocking, null, 2)}`,
    (d) => emit({ type: "token", agent: "debugger", text: d }),
    8000
  );
  account(dbgOut);
  const patched = parseFiles(dbgOut.text);
  const fixes: Fix[] = blocking.map((i) => ({
    issueId: i.id,
    file: i.file,
    summary: i.title,
  }));
  issuesFixed += fixes.length;
  // Merge patched files over the agent-authored set.
  for (const pf of patched) {
    const idx = appFiles.findIndex((f) => f.path === pf.path);
    if (idx >= 0) appFiles[idx] = pf;
    else appFiles.push(pf);
    emit({ type: "file", file: pf });
  }
  emit({ type: "fixes", fixes, iteration });
  emit({ type: "phase", agent: "debugger", status: "done" });
  iteration++;
}
